using System; using System.Data; using System.Data.SQLite; using System.Drawing; using System.IO; using System.Windows.Forms; using Microsoft.VisualBasic; using ClinicQueueSystem.Data; using ClinicQueueSystem.Services;
namespace ClinicQueueSystem.Forms
{
 public class AdminForm:Form
 {
  int uid; string role; TabControl tabs=new TabControl{Dock=DockStyle.Fill};
  public AdminForm(int userId,string userRole){uid=userId;role=userRole;Text="Clinic Queue System - Administration";Width=1200;Height=750;StartPosition=FormStartPosition.CenterParent;Controls.Add(tabs);Build();}
  void Build(){tabs.TabPages.Add(EntityTab("Departments","SELECT id,code,name,default_price,active FROM departments ORDER BY display_order,id",Department));tabs.TabPages.Add(EntityTab("Doctors","SELECT id,name,room_number,specialization,default_price,active FROM doctors ORDER BY name",Doctor));tabs.TabPages.Add(EntityTab("Shifts","SELECT id,name,start_time,end_time,active FROM shifts ORDER BY display_order,id",Shift));tabs.TabPages.Add(EntityTab("Printers","SELECT id,name,system_printer_name,connection_type,paper_width,active FROM printers ORDER BY name",Printer));tabs.TabPages.Add(EntityTab("Counters","SELECT c.id,c.counter_number,c.name,c.location,COALESCE(p.name,'') printer,c.active FROM counters c LEFT JOIN printers p ON p.id=c.printer_id ORDER BY c.counter_number",Counter));tabs.TabPages.Add(EntityTab("Users","SELECT id,username,full_name,role,active FROM users ORDER BY username",User));tabs.TabPages.Add(TicketsTab());tabs.TabPages.Add(ReportsTab());tabs.TabPages.Add(SettingsTab());tabs.TabPages.Add(AuditTab());tabs.TabPages.Add(BackupTab());}
  TabPage EntityTab(string title,string sql,Action<DataGridView,bool> action){var t=new TabPage(title);var bar=new FlowLayoutPanel{Dock=DockStyle.Top,Height=50,Padding=new Padding(8)};var add=B("ADD");var edit=B("EDIT");var deact=B("DEACTIVATE");bar.Controls.Add(add);bar.Controls.Add(edit);bar.Controls.Add(deact);t.Controls.Add(bar);var g=Grid();t.Controls.Add(g);void load(){Fill(g,sql);}add.Click+=(s,e)=>{action(g,false);load();};edit.Click+=(s,e)=>{action(g,true);load();};deact.Click+=(s,e)=>{if(g.CurrentRow==null)return;int id=Convert.ToInt32(g.CurrentRow.Cells[0].Value);if(MessageBox.Show("Deactivate selected record?","Confirm",MessageBoxButtons.YesNo,MessageBoxIcon.Question)==DialogResult.Yes)Deactivate(title,id);load();};load();return t;}
  Button B(string x){return new Button{Text=x,Width=110,Height=32};} DataGridView Grid(){return new DataGridView{Dock=DockStyle.Fill,ReadOnly=true,AllowUserToAddRows=false,AutoSizeColumnsMode=DataGridViewAutoSizeColumnsMode.Fill,SelectionMode=DataGridViewSelectionMode.FullRowSelect};} void Fill(DataGridView g,string sql){var dt=new DataTable();using(var c=Database.Open())using(var a=new SQLiteDataAdapter(sql,c))a.Fill(dt);g.DataSource=dt;}
  void Deactivate(string entity,int id){string table=entity=="Departments"?"departments":entity=="Doctors"?"doctors":entity=="Shifts"?"shifts":entity=="Printers"?"printers":entity=="Counters"?"counters":"users";using(var c=Database.Open())using(var cmd=new SQLiteCommand("UPDATE "+table+" SET active=0 WHERE id=@id",c)){cmd.Parameters.AddWithValue("@id",id);cmd.ExecuteNonQuery();Audit("DEACTIVATE",table,id,"Record deactivated");}}
  void Department(DataGridView g,bool edit){int id=edit?Id(g):-1;string code=Ask("Department code",edit?Val(g,1):"");string name=Ask("Department name",edit?Val(g,2):"");if(string.IsNullOrWhiteSpace(code)||string.IsNullOrWhiteSpace(name))return;decimal price=Dec(Ask("Default fee",edit?Val(g,3):"0"));int order=Int(Ask("Display order",edit?"1":"1"));using(var c=Database.Open()){string sql=edit?"UPDATE departments SET code=@c,name=@n,default_price=@p,display_order=@o,updated_at=@a WHERE id=@id":"INSERT INTO departments(code,name,default_price,display_order,active,created_at,updated_at) VALUES(@c,@n,@p,@o,1,@a,@a)";using(var cmd=new SQLiteCommand(sql,c)){cmd.Parameters.AddWithValue("@c",code);cmd.Parameters.AddWithValue("@n",name);cmd.Parameters.AddWithValue("@p",price);cmd.Parameters.AddWithValue("@o",order);cmd.Parameters.AddWithValue("@a",DateTime.Now.ToString("s"));if(edit)cmd.Parameters.AddWithValue("@id",id);cmd.ExecuteNonQuery();Audit(edit?"UPDATE_DEPARTMENT":"CREATE_DEPARTMENT","departments",edit?id:0,"Department "+name);}}}
  void Doctor(DataGridView g,bool edit){int id=edit?Id(g):-1;string name=Ask("Doctor name",edit?Val(g,1):"");if(string.IsNullOrWhiteSpace(name))return;string room=Ask("Room",edit?Val(g,2):"");string spec=Ask("Specialization",edit?Val(g,3):"");decimal fee=Dec(Ask("Default fee",edit?Val(g,4):"0"));using(var c=Database.Open()){string sql=edit?"UPDATE doctors SET name=@n,room_number=@r,specialization=@s,default_price=@p,updated_at=@a WHERE id=@id":"INSERT INTO doctors(name,room_number,specialization,default_price,active,created_at,updated_at) VALUES(@n,@r,@s,@p,1,@a,@a)";using(var cmd=new SQLiteCommand(sql,c)){cmd.Parameters.AddWithValue("@n",name);cmd.Parameters.AddWithValue("@r",room);cmd.Parameters.AddWithValue("@s",spec);cmd.Parameters.AddWithValue("@p",fee);cmd.Parameters.AddWithValue("@a",DateTime.Now.ToString("s"));if(edit)cmd.Parameters.AddWithValue("@id",id);cmd.ExecuteNonQuery();if(!edit)id=Convert.ToInt32(c.LastInsertRowId); } } AssignDoctor(id);Audit(edit?"UPDATE_DOCTOR":"CREATE_DOCTOR","doctors",id,"Doctor "+name);}
  void AssignDoctor(int doctorId){using(var c=Database.Open()){var dt=new DataTable();using(var a=new SQLiteDataAdapter("SELECT id,code||' - '||name name FROM departments WHERE active=1 ORDER BY display_order",c))a.Fill(dt);string list="Available departments:\n";foreach(DataRow r in dt.Rows)list+=r["id"]+" = "+r["name"]+"\n";string input=Interaction.InputBox(list+"\nEnter department IDs comma-separated (blank keeps current):","Doctor departments","");if(string.IsNullOrWhiteSpace(input))return;Database.Execute(c,null,"DELETE FROM doctor_departments WHERE doctor_id="+doctorId);foreach(var x in input.Split(',')){int d;if(int.TryParse(x.Trim(),out d))using(var cmd=new SQLiteCommand("INSERT OR IGNORE INTO doctor_departments(doctor_id,department_id,active) VALUES(@doc,@dep,1)",c)){cmd.Parameters.AddWithValue("@doc",doctorId);cmd.Parameters.AddWithValue("@dep",d);cmd.ExecuteNonQuery();}}}}
  void Shift(DataGridView g,bool edit){int id=edit?Id(g):-1;string name=Ask("Shift name",edit?Val(g,1):"");string start=Ask("Start time HH:mm",edit?Val(g,2):"08:00");string end=Ask("End time HH:mm",edit?Val(g,3):"14:00");if(!TimeSpan.TryParse(start,out _)||!TimeSpan.TryParse(end,out _)){MessageBox.Show("Invalid time.");return;}using(var c=Database.Open())using(var cmd=new SQLiteCommand(edit?"UPDATE shifts SET name=@n,start_time=@s,end_time=@e WHERE id=@id":"INSERT INTO shifts(name,start_time,end_time,active,display_order) VALUES(@n,@s,@e,1,99)",c)){cmd.Parameters.AddWithValue("@n",name);cmd.Parameters.AddWithValue("@s",start);cmd.Parameters.AddWithValue("@e",end);if(edit)cmd.Parameters.AddWithValue("@id",id);cmd.ExecuteNonQuery();Audit(edit?"UPDATE_SHIFT":"CREATE_SHIFT","shifts",id,"Shift "+name);}}
  void Printer(DataGridView g,bool edit){int id=edit?Id(g):-1;string name=Ask("Printer name",edit?Val(g,1):"");string sys=Ask("Windows printer name (exact)",edit?Val(g,2):"");string type=Ask("Connection type",edit?Val(g,3):"WINDOWS");int width=Int(Ask("Paper width (mm)",edit?Val(g,4):"80"));using(var c=Database.Open())using(var cmd=new SQLiteCommand(edit?"UPDATE printers SET name=@n,system_printer_name=@s,connection_type=@t,paper_width=@w WHERE id=@id":"INSERT INTO printers(name,system_printer_name,connection_type,paper_width,active) VALUES(@n,@s,@t,@w,1)",c)){cmd.Parameters.AddWithValue("@n",name);cmd.Parameters.AddWithValue("@s",sys);cmd.Parameters.AddWithValue("@t",type);cmd.Parameters.AddWithValue("@w",width);if(edit)cmd.Parameters.AddWithValue("@id",id);cmd.ExecuteNonQuery();Audit(edit?"UPDATE_PRINTER":"CREATE_PRINTER","printers",id,"Printer "+name);}}
  void Counter(DataGridView g,bool edit){int id=edit?Id(g):-1;string no=Ask("Counter number",edit?Val(g,1):"");string name=Ask("Counter name",edit?Val(g,2):"");string loc=Ask("Location",edit?Val(g,3):"");int pid=Int(Ask("Printer ID (blank/0 for none)","0"));using(var c=Database.Open())using(var cmd=new SQLiteCommand(edit?"UPDATE counters SET counter_number=@n,name=@nm,location=@l,printer_id=@p WHERE id=@id":"INSERT INTO counters(counter_number,name,location,printer_id,active) VALUES(@n,@nm,@l,@p,1)",c)){cmd.Parameters.AddWithValue("@n",no);cmd.Parameters.AddWithValue("@nm",name);cmd.Parameters.AddWithValue("@l",loc);cmd.Parameters.AddWithValue("@p",pid>0?(object)pid:DBNull.Value);if(edit)cmd.Parameters.AddWithValue("@id",id);cmd.ExecuteNonQuery();Audit(edit?"UPDATE_COUNTER":"CREATE_COUNTER","counters",id,"Counter "+name);}}
  void User(DataGridView g,bool edit){int id=edit?Id(g):-1;string un=Ask("Username",edit?Val(g,1):"");string full=Ask("Full name",edit?Val(g,2):"");string r=Ask("Role ADMIN / SUPERVISOR / RECEPTIONIST",edit?Val(g,3):"RECEPTIONIST").ToUpper();if(r!="ADMIN"&&r!="SUPERVISOR"&&r!="RECEPTIONIST")r="RECEPTIONIST";string pw=Ask("Password (leave blank when editing to keep current)","");using(var c=Database.Open()){if(edit){string sql=string.IsNullOrWhiteSpace(pw)?"UPDATE users SET username=@u,full_name=@f,role=@r,updated_at=@a WHERE id=@id":"UPDATE users SET username=@u,full_name=@f,role=@r,password_hash=@p,updated_at=@a WHERE id=@id";using(var cmd=new SQLiteCommand(sql,c)){cmd.Parameters.AddWithValue("@u",un);cmd.Parameters.AddWithValue("@f",full);cmd.Parameters.AddWithValue("@r",r);cmd.Parameters.AddWithValue("@a",DateTime.Now.ToString("s"));if(!string.IsNullOrWhiteSpace(pw))cmd.Parameters.AddWithValue("@p",PasswordHasher.Hash(pw));cmd.Parameters.AddWithValue("@id",id);cmd.ExecuteNonQuery();}}else{if(string.IsNullOrWhiteSpace(pw))pw="admin123";using(var cmd=new SQLiteCommand("INSERT INTO users(username,password_hash,full_name,role,active,created_at,updated_at) VALUES(@u,@p,@f,@r,1,@a,@a)",c)){cmd.Parameters.AddWithValue("@u",un);cmd.Parameters.AddWithValue("@p",PasswordHasher.Hash(pw));cmd.Parameters.AddWithValue("@f",full);cmd.Parameters.AddWithValue("@r",r);cmd.Parameters.AddWithValue("@a",DateTime.Now.ToString("s"));cmd.ExecuteNonQuery();}}Audit(edit?"UPDATE_USER":"CREATE_USER","users",id,"User "+un);}}
  TabPage TicketsTab(){var t=new TabPage("Tickets");var bar=new FlowLayoutPanel{Dock=DockStyle.Top,Height=55};var from=new DateTimePicker{Value=DateTime.Today};var to=new DateTimePicker{Value=DateTime.Today};var refresh=B("REFRESH");var voidb=B("VOID");bar.Controls.Add(new Label{Text="From",AutoSize=true,Padding=new Padding(5,8,0,0)});bar.Controls.Add(from);bar.Controls.Add(new Label{Text="To",AutoSize=true,Padding=new Padding(5,8,0,0)});bar.Controls.Add(to);bar.Controls.Add(refresh);bar.Controls.Add(voidb);t.Controls.Add(bar);var g=Grid();t.Controls.Add(g);Action load=()=>Fill(g,"SELECT t.id,t.ticket_number,t.ticket_date,t.ticket_time,d.name department,COALESCE(doc.name,'') doctor,s.name shift,t.price,t.status,t.print_count,t.void_reason FROM tickets t JOIN departments d ON d.id=t.department_id LEFT JOIN doctors doc ON doc.id=t.doctor_id JOIN shifts s ON s.id=t.shift_id WHERE t.ticket_date BETWEEN '"+from.Value.ToString("yyyy-MM-dd")+"' AND '"+to.Value.ToString("yyyy-MM-dd")+"' ORDER BY t.id DESC");refresh.Click+=(s,e)=>load();voidb.Click+=(s,e)=>{if(g.CurrentRow==null)return;long id=Convert.ToInt64(g.CurrentRow.Cells[0].Value);string reason=Ask("Void reason","Operator requested void");if(!string.IsNullOrWhiteSpace(reason)){QueueService.Void(id,uid,reason);load();}};load();return t;}
  TabPage ReportsTab(){var t=new TabPage("Reports");var p=new FlowLayoutPanel{Dock=DockStyle.Top,Height=80,Padding=new Padding(12)};var from=new DateTimePicker{Value=DateTime.Today};var to=new DateTimePicker{Value=DateTime.Today};var export=B("EXPORT CSV");var summary=B("SUMMARY");p.Controls.Add(new Label{Text="From"});p.Controls.Add(from);p.Controls.Add(new Label{Text="To"});p.Controls.Add(to);p.Controls.Add(export);p.Controls.Add(summary);t.Controls.Add(p);var outp=new TextBox{Multiline=true,ReadOnly=true,Dock=DockStyle.Fill,Font=new Font("Consolas",11)};t.Controls.Add(outp);Action show=()=>{using(var c=Database.Open())using(var cmd=new SQLiteCommand("SELECT COUNT(*),COALESCE(SUM(CASE WHEN status<>'VOID' THEN price ELSE 0 END),0),SUM(CASE WHEN status='VOID' THEN 1 ELSE 0 END) FROM tickets WHERE ticket_date BETWEEN @f AND @t",c)){cmd.Parameters.AddWithValue("@f",from.Value.ToString("yyyy-MM-dd"));cmd.Parameters.AddWithValue("@t",to.Value.ToString("yyyy-MM-dd"));using(var r=cmd.ExecuteReader()){r.Read();outp.Text="TICKET SUMMARY\r\n===========================\r\nTickets: "+r[0]+"\r\nRevenue: Rs "+Convert.ToDecimal(r[1]).ToString("N2")+"\r\nVoided: "+(r[2]==DBNull.Value?0:r[2])+"\r\n\r\nBy Department:\r\n";} }using(var c=Database.Open())using(var cmd=new SQLiteCommand("SELECT d.code,d.name,COUNT(*),COALESCE(SUM(CASE WHEN t.status<>'VOID' THEN t.price ELSE 0 END),0) FROM tickets t JOIN departments d ON d.id=t.department_id WHERE t.ticket_date BETWEEN @f AND @t GROUP BY d.id ORDER BY d.display_order",c)){cmd.Parameters.AddWithValue("@f",from.Value.ToString("yyyy-MM-dd"));cmd.Parameters.AddWithValue("@t",to.Value.ToString("yyyy-MM-dd"));using(var r=cmd.ExecuteReader()){while(r.Read())outp.AppendText(r[0]+" - "+r[1]+": "+r[2]+" tickets, Rs "+Convert.ToDecimal(r[3]).ToString("N2")+"\r\n");}}};summary.Click+=(s,e)=>show();export.Click+=(s,e)=>{using(var d=new SaveFileDialog{Filter="CSV (*.csv)|*.csv",FileName="tickets_"+DateTime.Now.ToString("yyyyMMdd_HHmm")+".csv"})if(d.ShowDialog()==DialogResult.OK){CsvExporter.ExportTickets(from.Value.Date,to.Value.Date,d.FileName);MessageBox.Show("CSV exported.");}};show();return t;}
  TabPage SettingsTab(){var t=new TabPage("Settings");var g=Grid();t.Controls.Add(g);var bar=new FlowLayoutPanel{Dock=DockStyle.Top,Height=50};var edit=B("EDIT");bar.Controls.Add(edit);t.Controls.Add(bar);Action load=()=>Fill(g,"SELECT key,value FROM settings ORDER BY key");edit.Click+=(s,e)=>{if(g.CurrentRow==null)return;string key=Val(g,0);string val=Ask(key,Val(g,1));using(var c=Database.Open())using(var cmd=new SQLiteCommand("UPDATE settings SET value=@v WHERE key=@k",c)){cmd.Parameters.AddWithValue("@v",val);cmd.Parameters.AddWithValue("@k",key);cmd.ExecuteNonQuery();Audit("UPDATE_SETTING","settings",0,key+" updated");}load();};load();return t;}
  TabPage AuditTab(){var t=new TabPage("Audit Log");var g=Grid();t.Controls.Add(g);Fill(g,"SELECT id,created_at,user_id,action,entity_type,entity_id,description FROM audit_logs ORDER BY id DESC LIMIT 2000");return t;}
  TabPage BackupTab(){var t=new TabPage("Backup / Restore");var p=new FlowLayoutPanel{Dock=DockStyle.Top,Height=100,Padding=new Padding(20)};var backup=B("BACKUP DATABASE");var restore=B("RESTORE DATABASE");p.Controls.Add(backup);p.Controls.Add(restore);t.Controls.Add(p);var info=new Label{Text="Backup copies the SQLite database while the application is open. Restore closes the app after replacing the database file.",Dock=DockStyle.Top,Height=70,Padding=new Padding(20)};t.Controls.Add(info);backup.Click+=(s,e)=>{using(var d=new SaveFileDialog{Filter="SQLite DB (*.db)|*.db",FileName="clinic_queue_backup_"+DateTime.Now.ToString("yyyyMMdd_HHmmss")+".db"})if(d.ShowDialog()==DialogResult.OK){File.Copy(Database.DbFile,d.FileName,true);MessageBox.Show("Backup created.");}};restore.Click+=(s,e)=>{if(MessageBox.Show("Restore will replace the current database and close the application. Continue?","Warning",MessageBoxButtons.YesNo,MessageBoxIcon.Warning)!=DialogResult.Yes)return;using(var d=new OpenFileDialog{Filter="SQLite DB (*.db)|*.db"})if(d.ShowDialog()==DialogResult.OK){File.Copy(d.FileName,Database.DbFile,true);MessageBox.Show("Database restored. The application will close now.");Application.Exit();}};return t;}
  static string Ask(string prompt,string def){return Interaction.InputBox(prompt,"Clinic Queue System",def);}static int Int(string s){int x;return int.TryParse(s,out x)?x:0;}static decimal Dec(string s){decimal x;return decimal.TryParse(s,out x)?x:0;}int Id(DataGridView g){return Convert.ToInt32(g.CurrentRow.Cells[0].Value);}string Val(DataGridView g,int i){return Convert.ToString(g.CurrentRow.Cells[i].Value)??"";}void Audit(string a,string e,int id,string d){using(var c=Database.Open())using(var cmd=new SQLiteCommand("INSERT INTO audit_logs(user_id,action,entity_type,entity_id,description,created_at) VALUES(@u,@a,@e,@id,@d,@t)",c)){cmd.Parameters.AddWithValue("@u",uid);cmd.Parameters.AddWithValue("@a",a);cmd.Parameters.AddWithValue("@e",e);cmd.Parameters.AddWithValue("@id",id>0?(object)id:DBNull.Value);cmd.Parameters.AddWithValue("@d",d);cmd.Parameters.AddWithValue("@t",DateTime.Now.ToString("s"));cmd.ExecuteNonQuery();}}
 }
}
